F2 = [['hi 调度失败', '0/3 nodes: 2 Insufficient cpu'], ['抢占', 'nominatedNodeName = worker2'], ['low3 终止', '宽限期 12 s'], ['hi Running', '+13.1 s']]
F3 = [['worker', 'a-low1, a-low2(100)'], ['worker2', 'b-mid1, b-mid2(500)'], ['hi(1000)', '选了 worker'], ['被抢占的', 'a-low2']]
